// Agrega todas as linhas do BigQuery em um único objeto JSON
const rows = $input.all().map(item => ({
  BU:                       item.json.BU                       ?? null,
  Product:                  item.json.Product                  ?? null,
  Macro_BU:                 item.json.Macro_BU                 ?? null,
  MES:                      item.json.MES                      ?? null,
  ANO:                      item.json.ANO                      ?? null,
  QUARTER:                  item.json.QUARTER                  ?? null,
  MNG_1:                    item.json.MNG_1                    ?? null,
  MNG_2:                    item.json.MNG_2                    ?? null,
  MNG_3:                    item.json.MNG_3                    ?? null,
  MNG_4:                    item.json.MNG_4                    ?? null,
  Cenario:                  item.json.Cenario                  ?? null,
  DICCIONARIO_LOCAL_EBIT:   item.json.DICCIONARIO_LOCAL_EBIT   ?? null,
  Value:                    typeof item.json.Value === 'string'
                              ? parseFloat(item.json.Value)
                              : (item.json.Value ?? 0)
}));

// Data/hora no fuso de São Paulo
const now = new Date();
const lastUpdated = now.toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit'
});

const jsonPayload = {
  last_updated: lastUpdated,
  row_count: rows.length,
  data: rows
};

// Converte para string JSON e depois para Base64 (UTF-8 safe)
const jsonString = JSON.stringify(jsonPayload);
const contentBase64 = Buffer.from(jsonString, 'utf-8').toString('base64');

return [{ json: { content_base64: contentBase64, row_count: rows.length, last_updated: lastUpdated } }];

// Combina o conteúdo Base64 (node anterior = Montar JSON)
// com o SHA atual do arquivo no GitHub

const jsonNode   = $('Montar JSON (agregar linhas)').first().json;
const githubNode = $('Buscar SHA atual (GitHub)').first().json;

// SHA é necessário para atualizar arquivo existente.
// Se o arquivo não existe ainda (primeiro deploy), sha fica undefined e o GitHub cria o arquivo.
const sha = githubNode?.sha ?? undefined;

const commitDate = new Date().toISOString().slice(0, 10);

const payload = {
  message: `update: P&L data (${commitDate}) - ${jsonNode.row_count} linhas`,
  content: jsonNode.content_base64,
  branch: 'main'
};

// Só inclui sha se o arquivo já existir
if (sha) payload.sha = sha;

return [{ json: payload }];
